const input = $input.first().json;
const body = input.body || input;

// Колонки результата. Список ОБЩИЙ со скриптом Apps Script:
// он обязан совпадать 1:1 с константой RESULT_HEADERS в файле `code`.
// Дальше по цепочке список едет в meta.result_fields, поэтому нода
// Prepare Sheet Update берёт его отсюда и своей копии не держит.
const RESULT_FIELDS = [
  'transcription_received_at',
  'transcription_error',
  'call_duration_seconds',
  'call_duration',
  'transcript_text',
  'transcript_left',
  'transcript_right',
  'summary',
  'overall_score',
  'problem_level',
  'is_problem_call',
  'main_strength',
  'main_error',
  'recommended_feedback',
  'is_target_call',
  'non_target_reason',
  'non_target_detail',
  'no_booking_reason',
  'no_booking_detail',
  'is_primary_patient',
  'requested_specialist_raw',
  'requested_specialist',
  'requested_specialist_bitrix_user_id',
  'requested_specialist_match_status',
  'requested_specialist_match_comment',
  'is_appointment_booked',
  'appointment_specialist_raw',
  'appointment_specialist',
  'appointment_specialist_bitrix_user_id',
  'appointment_specialist_match_status',
  'appointment_specialist_match_comment',
  'appointment_datetime',
  'city',
  'referral_source',
  'rule_results_json',
  'prompt_version',
  'transcription_n8n_execution_id'
];

if (body.action !== 'transcribe_and_analyze_call') {
  throw new Error(`Unknown action: ${body.action}`);
}

if (!body.call_key) throw new Error('Missing call_key');
if (!body.drive_file_id) throw new Error('Missing drive_file_id');

// Координаты записи результата: результат пишется прямо в Google Sheets,
// callback в Apps Script больше не используется.
if (!body.spreadsheet_id) throw new Error('Missing spreadsheet_id');
if (!body.sheet_name) throw new Error('Missing sheet_name');

const rowNumber = Number(body.row_number);

if (!Number.isInteger(rowNumber) || rowNumber < 2) {
  throw new Error(`Invalid row_number: ${body.row_number} (expected integer >= 2)`);
}

const resultColumns = body.result_columns;

if (!resultColumns || typeof resultColumns !== 'object' || Array.isArray(resultColumns)) {
  throw new Error('Missing result_columns object');
}

const normalizedColumns = {};
const missingColumns = [];
const invalidColumns = [];

for (const field of RESULT_FIELDS) {
  const letter = String(resultColumns[field] ?? '').trim().toUpperCase();

  if (!letter) {
    missingColumns.push(field);
    continue;
  }

  if (!/^[A-Z]{1,3}$/.test(letter)) {
    invalidColumns.push(`${field}=${resultColumns[field]}`);
    continue;
  }

  normalizedColumns[field] = letter;
}

if (missingColumns.length) {
  throw new Error(`Missing result_columns for: ${missingColumns.join(', ')}`);
}

if (invalidColumns.length) {
  throw new Error(`Invalid column letters in result_columns: ${invalidColumns.join(', ')}`);
}

if (!body.prompts?.transcription_prompt) {
  throw new Error('Missing prompts.transcription_prompt');
}

if (!Array.isArray(body.prompts?.evaluation_rules) || body.prompts.evaluation_rules.length === 0) {
  throw new Error('Missing prompts.evaluation_rules');
}

const tempId = `mango_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;

return [
  {
    json: {
      action: body.action,

      call_key: body.call_key,
      filename_fixed: body.filename_fixed || '',

      call_datetime: body.call_datetime || '',
      call_date: body.call_date || '',
      call_time: body.call_time || '',

      direction: body.direction || '',
      client_phone: body.client_phone || '',
      mango_side: body.mango_side || '',
      line_name: body.line_name || '',
      // Оператор уже итоговый: матчинг выполнил Apps Script при скане,
      // здесь значение только переносится дальше.
      operator_name: body.operator_name || '',

      // ПЕРЕХОДНОЕ ПОЛЕ. Справочник сотрудников живёт в staticData
      // workflow (ветка Webhook Employees Directory), Prepare Sheet Update
      // читает его оттуда. Здесь снимок остаётся необязательным fallback
      // на время, пока Apps Script ещё кладёт его в payload; после
      // переходной недели поле уходит и отсюда, и из Apps Script.
      // В промпт AI этот список НЕ попадает.
      employees: Array.isArray(body.employees) ? body.employees : [],

      drive_file_id: body.drive_file_id,
      drive_url: body.drive_url || '',

      spreadsheet_id: body.spreadsheet_id,
      sheet_name: body.sheet_name,
      row_number: rowNumber,
      result_columns: normalizedColumns,
      result_fields: RESULT_FIELDS,

      prompt_version: body.prompt_version || body.prompts.prompt_version || '',

      prompts: {
        prompt_version: body.prompts.prompt_version || body.prompt_version || '',
        transcription_prompt: body.prompts.transcription_prompt || '',
        analysis_system_prompt: body.prompts.analysis_system_prompt || '',
        output_schema: body.prompts.output_schema || '',
        evaluation_rules: body.prompts.evaluation_rules
      },

      temp: {
        id: tempId,
        inputPath: `/tmp/${tempId}.mp3`,
        leftPath: `/tmp/${tempId}_left.wav`,
        rightPath: `/tmp/${tempId}_right.wav`,
        splitLogPath: `/tmp/${tempId}_split.log`
      }
    }
  }
];

const meta = $items('Normalize Incoming Payload')[0].json;
const current = $input.first();

if (!current.binary || !current.binary.audio) {
  throw new Error('Google Drive node did not return binary field "audio"');
}

return [
  {
    json: meta,
    binary: {
      audio: current.binary.audio
    }
  }
];

const meta = $items('Attach Meta To Audio')[0].json;

if (!meta.temp?.inputPath || !meta.temp?.leftPath || !meta.temp?.rightPath) {
  throw new Error('Missing temp paths before FFmpeg Split Channels');
}

return [
  {
    json: meta
  }
];

const out = $input.first().json;
const meta = $items('Prepare FFmpeg Input')[0].json;

const text =
  out.text ||
  out.transcript ||
  out.transcription ||
  out.data?.text ||
  out.message?.content ||
  out.output ||
  '';

if (!text) {
  throw new Error('Empty left channel transcript');
}

return [
  {
    json: {
      ...meta,
      channel: 'left',
      transcript_left: String(text).trim()
    }
  }
];

const out = $input.first().json;
const meta = $items('Prepare FFmpeg Input')[0].json;

const text =
  out.text ||
  out.transcript ||
  out.transcription ||
  out.data?.text ||
  out.message?.content ||
  out.output ||
  '';

if (!text) {
  throw new Error('Empty right channel transcript');
}

return [
  {
    json: {
      ...meta,
      channel: 'right',
      transcript_right: String(text).trim()
    }
  }
];

// Сборка запроса к LLM.
//
// ПОРЯДОК СООБЩЕНИЙ ПОДЧИНЁН КЭШУ OpenAI (prompt caching):
// весь статичный текст — единым префиксом в system, переменные данные
// звонка — строго в конце, в user. System-строка обязана быть побайтово
// одинаковой между запросами: ни дат, ни execution id, ни prompt_version
// в неё не попадает, иначе префикс каждый раз новый и кэш не срабатывает.
// Любое добавление в system переменных значений убивает экономию — при
// правках это главное, что нужно сохранить.
//
// Проверка эффекта: в usage ответа prompt_tokens_details.cached_tokens > 0
// начиная со второго звонка в потоке.

// --- Пороги «короткого» звонка ----------------------------------------
// Обрывы, тишина, гудки, ошиблись номером. Гонять по ним полный анализ
// (правила + рассуждения) бессмысленно и дорого, поэтому для них
// собирается сокращённый промпт: только классификация. Оценка по правилам
// таким звонкам проставляется кодом в ноде Prepare Sheet Update как N/A.
const SHORT_TRANSCRIPT_CHARS = 300;
const SHORT_CALL_SECONDS = 20;

const leftItem = $items('Prepare Left Transcript')[0]?.json || {};
const rightItem = $items('Prepare Right Transcript')[0]?.json || {};
const baseMeta = $items('Prepare FFmpeg Input')[0]?.json || {};

// Длительность звонка. Её считает ffprobe в ноде FFmpeg Split Channels
// по ИСХОДНОМУ файлу (до разделения на каналы и до резки тишины) и
// печатает строкой DUR=<секунды>. Сбой ffprobe транскрибацию не ломает:
// обе колонки длительности просто останутся пустыми.
function parseCallDurationSeconds(stdout) {
  const match = String(stdout ?? '').match(/^DUR=([0-9]+(?:\.[0-9]+)?)\s*$/m);

  if (!match) return null;

  const seconds = Math.round(Number(match[1]));

  return Number.isFinite(seconds) && seconds > 0 ? seconds : null;
}

// «4:07», при часе и более «1:02:33».
function formatCallDuration(seconds) {
  if (seconds === null) return '';

  const pad = n => String(n).padStart(2, '0');

  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const rest = seconds % 60;

  return hours > 0
    ? `${hours}:${pad(minutes)}:${pad(rest)}`
    : `${minutes}:${pad(rest)}`;
}

let callDurationSeconds = null;

try {
  callDurationSeconds = parseCallDurationSeconds($items('FFmpeg Split Channels')[0]?.json?.stdout);
} catch (e) {
  callDurationSeconds = null;
}

const meta = {
  ...baseMeta,
  ...leftItem,
  ...rightItem
};

if (!leftItem.transcript_left) {
  throw new Error('No transcript_left');
}

if (!rightItem.transcript_right) {
  throw new Error('No transcript_right');
}

const transcriptChannels = {
  left: leftItem.transcript_left,
  right: rightItem.transcript_right
};

const transcriptText = [
  'Двухканальная запись телефонного разговора.',
  '',
  'Канал left:',
  transcriptChannels.left,
  '',
  'Канал right:',
  transcriptChannels.right
].join('\n');

const transcriptLength = transcriptChannels.left.length + transcriptChannels.right.length;

const isShortCall =
  transcriptLength < SHORT_TRANSCRIPT_CHARS ||
  (callDurationSeconds !== null && callDurationSeconds < SHORT_CALL_SECONDS);

const analysisMode = isShortCall ? 'short' : 'full';

// --- Схема ответа -----------------------------------------------------
// Описания полей здесь — единственное место с подробными формулировками:
// инструкции ниже на них ссылаются и правила не дублируют (иначе один и
// тот же текст едет в промпт дважды). JSON.stringify без отступов: они
// стоят токенов и модели ничего не дают.

const channelRolesSchema = {
  left: 'operator | client | unknown',
  right: 'operator | client | unknown',
  confidence: 'low | medium | high',
  reason: 'почему роли распределены именно так, до 15 слов'
};

const defaultSchema = {
  summary: 'Краткое содержание звонка, до 40 слов',
  overall_score: 'Число 1-5, взвешенная итоговая оценка без учета N/A',
  problem_level: 'NONE | LOW | MEDIUM | HIGH | CRITICAL',
  is_problem_call: 'boolean',
  channel_roles: channelRolesSchema,
  main_strength: 'Главная сильная сторона оператора, до 15 слов',
  main_error: 'Главная ошибка оператора, до 15 слов',
  recommended_feedback: 'Краткая рекомендация для обратной связи оператору, до 20 слов',
  is_target_call: 'boolean — true, если обратился потенциальный или действующий пациент по вопросам приёма, лечения, записи, переноса, результатов И клиника в принципе могла дать то, что он хотел. false — мы не могли или не стали удовлетворять запрос (см. non_target_reason)',
  non_target_reason: "если is_target_call = false — строго одна категория: spam (спам, реклама, ошиблись номером) | no_service (нужной услуги или специалиста нет) | wrong_city (услуга есть, но не в городе клиента) | no_slots (нет подходящего времени в расписании) | off_hours (хотел приём в нерабочее время) | price (не устроила цена и разговор на этом закончился) | other; иначе пустая строка",
  non_target_detail: 'если is_target_call = false — что именно хотел звонящий, свободным текстом, до 15 слов (например: МРТ коленного сустава, травматолог в Кургане); иначе пустая строка',
  no_booking_reason: "если звонок целевой (is_target_call = true), но запись НЕ состоялась (is_appointment_booked = false) — строго одна категория: thinking (взял паузу подумать) | price (смутила цена, но услугу мы дать могли) | info_only (просто узнавал цену или информацию, записываться не собирался) | callback (сказал, что перезвонит сам) | declined (отказался в ходе диалога) | other; иначе пустая строка",
  no_booking_detail: 'если заполнен no_booking_reason — детали свободным текстом, до 15 слов (что смутило, что узнавал); иначе пустая строка',
  is_primary_patient: "строго одно из: primary | repeat | unknown. primary — впервые обращается в клинику, repeat — уже был пациентом (упоминает прошлые визиты, продление, оператор находит карту), unknown — из разговора не ясно",
  requested_specialist_raw: 'желаемый врач или специалист, ровно так, как прозвучал в разговоре. Заполняй ТОЛЬКО если клиент целенаправленно хотел записаться к конкретному специалисту: назвал его сам или пришёл по рекомендации именно к нему. Если специалиста предложил оператор — пустая строка. Не выдумывай ФИО, не исправляй фамилии, не выбирай из памяти или списка. Не уверен — пустая строка',
  is_appointment_booked: 'boolean — true только если в звонке согласованы конкретные дата и время приёма',
  appointment_specialist_raw: 'специалист, к которому фактически записали пациента, ровно так, как прозвучало. Те же правила, что у requested_specialist_raw. Если записи не было или не уверен — пустая строка',
  appointment_datetime: 'если запись состоялась — дата и время приёма, как прозвучали в разговоре; иначе пустая строка',
  city: 'город клиента, ТОЛЬКО если он явно прозвучал в разговоре (клиент сказал откуда он, спрашивал про филиал в городе). Не угадывай по номеру телефона; не прозвучало — пустая строка',
  referral_source: 'откуда клиент узнал о клинике, ТОЛЬКО если явно прозвучало (2ГИС, интернет, сайт, по рекомендации, реклама); иначе пустая строка',
  rule_results: [
    {
      rule_id: 'строго один из rule_id из evaluation_rules',
      score: 'число 1-5 или null если N/A',
      is_na: 'boolean',
      reason: 'почему такая оценка, до 15 слов',
      evidence: 'фрагмент или наблюдение из звонка, до 15 слов',
      recommendation: 'что улучшить. Заполняй ТОЛЬКО при score <= 3, иначе пустая строка'
    }
  ]
};

// Сокращённая схема для коротких звонков: оценки по правилам у них нет,
// поля результата проставляет код в Prepare Sheet Update.
const shortSchema = {
  summary: defaultSchema.summary,
  channel_roles: channelRolesSchema,
  is_target_call: defaultSchema.is_target_call,
  non_target_reason: defaultSchema.non_target_reason,
  non_target_detail: defaultSchema.non_target_detail
};

// --- Статичный префикс (system) ---------------------------------------

const baseSystemPrompt = meta.prompts.analysis_system_prompt || [
  'Ты анализируешь звонки операторов клиники TEMED.',
  'Оценивай звонок только по переданным evaluation_rules.',
  'Не добавляй новых правил от себя.',
  'Верни только валидный JSON без markdown.',
  'Не выдумывай факты, которых нет в транскрипте.',
  'Не оценивай клиническую правильность лечения.',
  'Не проверяй цены, скидки, акции, расписание, предоплату, рассрочку и коммерческие условия.'
].join(' ');

const channelsBlock = [
  'Важно про каналы:',
  '1. Запись стерео разделена на два канала: left и right.',
  '2. Один канал обычно содержит речь оператора, второй — речь клиента.',
  '3. Сначала определи, какой канал вероятнее оператор, а какой клиент.',
  '4. Если не уверен, укажи unknown и объясни причину.',
  '5. Оператор обычно представляется, говорит от имени клиники, задает вопросы, предлагает запись или следующий шаг.',
  '6. Клиент обычно отвечает на вопросы, описывает проблему, сомневается или задает уточняющие вопросы.'
];

// Инструкции держат только то, чего нет в схеме ответа: механику оценки
// по правилам. Всё, что касается отдельных полей, живёт в описаниях схемы —
// дублировать формулировки здесь нельзя, иначе промпт снова раздуется.
const fullInstructions = [
  'Инструкция:',
  '1. Оцени звонок по каждому правилу из evaluation_rules и верни результат с тем же rule_id. Новых rule_id не добавляй.',
  '2. Правило неприменимо и na_allowed = true → is_na = true, score = null. Правило применимо → is_na = false, score от 1 до 5.',
  '3. overall_score считай с учетом weight. N/A в overall_score не участвует.',
  '4. Если score <= critical_if_score_lte по любому правилу, problem_level минимум HIGH и is_problem_call = true.',
  '5. Если score <= problem_if_score_lte по любому правилу, problem_level минимум MEDIUM и is_problem_call = true.',
  '6. Не проверяй цены, скидки, акции, расписание и коммерческие условия.',
  '7. Нецелевой звонок (is_target_call = false) всё равно оцени по правилам, где это осмысленно; остальным ставь N/A, если na_allowed, иначе оценивай по факту.',
  '8. Остальные поля заполняй строго по описанию соответствующего поля в схеме ответа: там указаны допустимые значения, ограничения по длине и условия, когда поле остаётся пустым.',
  '9. Списка сотрудников у тебя нет: ФИО ни с каким списком не сопоставляй и фамилии не исправляй. Сопоставление с реальным сотрудником выполняется отдельно по справочнику.',
  '10. Обязательно добавь в JSON поле channel_roles. Верни только JSON без markdown.'
];

const shortInstructions = [
  'Инструкция:',
  '1. Звонок короткий: разговор не состоялся или оборвался. По правилам его не оценивай — оценка проставляется отдельно.',
  '2. Определи роли каналов и заполни channel_roles.',
  '3. Классифицируй звонок и заполни поля строго по описанию в схеме ответа.',
  '4. Верни только JSON без markdown.'
];

const fullSystemPrompt = [
  baseSystemPrompt,
  '',
  'Проанализируй двухканальную запись телефонного разговора оператора клиники TEMED.',
  '',
  ...channelsBlock,
  '',
  ...fullInstructions,
  '',
  'Правила оценки evaluation_rules:',
  JSON.stringify(meta.prompts.evaluation_rules),
  '',
  'Формат ответа:',
  meta.prompts.output_schema || JSON.stringify(defaultSchema)
].join('\n');

const shortSystemPrompt = [
  baseSystemPrompt,
  '',
  'Тебе передан короткий двухканальный звонок в клинику TEMED: разговор не состоялся, оборвался или содержит только гудки и тишину.',
  '',
  ...channelsBlock,
  '',
  ...shortInstructions,
  '',
  'Формат ответа:',
  JSON.stringify(shortSchema)
].join('\n');

const systemPrompt = isShortCall ? shortSystemPrompt : fullSystemPrompt;

// --- Переменная часть (user) ------------------------------------------
// call_key и client_phone в промпт не идут: модель их не использует,
// а телефон — лишние персональные данные в запросе к LLM.
const callMeta = [
  `Дата/время: ${meta.call_datetime}`,
  `Направление: ${meta.direction}`,
  `Наша сторона: ${meta.mango_side}`,
  `Линия: ${meta.line_name}`,
  `Оператор: ${meta.operator_name}`
].join('\n');

const userPrompt = [
  'Данные звонка:',
  callMeta,
  '',
  'Транскрипт канала left:',
  transcriptChannels.left,
  '',
  'Транскрипт канала right:',
  transcriptChannels.right
].join('\n');

// Тело запроса к proxyapi (/v1/chat/completions). reasoning_effort = low
// нода @n8n/n8n-nodes-langchain.openAi не умеет, поэтому запрос уходит
// обычной HTTP Request нодой. Формат ответа тот же: choices[0].message.content.
const llmBody = {
  model: 'gpt-5-mini',
  reasoning_effort: 'low',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return [
  {
    json: {
      ...meta,

      call_duration_seconds: callDurationSeconds === null ? '' : callDurationSeconds,
      call_duration: formatCallDuration(callDurationSeconds),

      transcript_text: transcriptText,
      transcript_channels: transcriptChannels,

      // Читает Prepare Sheet Update: в режиме short он сам проставляет
      // rule_results = N/A и пустой overall_score.
      analysis_mode: analysisMode,
      transcript_length: transcriptLength,

      systemPrompt,
      userPrompt,
      llmBody
    }
  }
];

const current = $input.first().json;
const meta = $items('Build Analysis Request')[0].json;

const raw =
  current.message?.content ||
  current.choices?.[0]?.message?.content ||
  current.output ||
  current.text ||
  current.response ||
  current.data ||
  '';

function parseJsonSafe(value) {
  if (typeof value === 'object' && value !== null) return value;

  const s = String(value || '').trim();
  if (!s) return null;

  try { return JSON.parse(s); } catch (e) {}

  const cleaned = s
    .replace(/^```json/i, '')
    .replace(/^```/i, '')
    .replace(/```$/i, '')
    .trim();

  try { return JSON.parse(cleaned); } catch (e) {}

  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');

  if (first !== -1 && last !== -1 && last > first) {
    try { return JSON.parse(cleaned.slice(first, last + 1)); } catch (e) {}
  }

  return null;
}

function normalizeProblemLevel(value) {
  const allowed = ['NONE', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];
  const s = String(value || '').trim().toUpperCase();
  return allowed.includes(s) ? s : 'NONE';
}

function normalizeBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;

  const s = String(value || '').trim().toLowerCase();
  if (['true', '1', 'yes', 'да', 'истина'].includes(s)) return true;
  if (['false', '0', 'no', 'нет', 'ложь'].includes(s)) return false;

  return false;
}

function normalizeEnum(value, allowed, fallback) {
  const s = String(value || '').trim().toLowerCase();
  return allowed.includes(s) ? s : fallback;
}

function normalizeScore(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  if (!Number.isFinite(n)) return null;
  if (n < 1) return 1;
  if (n > 5) return 5;
  return n;
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

let analysis = parseJsonSafe(raw);

// Невалидный JSON — звонок в любом случае едет на ручную проверку,
// и режим short этого не отменяет (см. блок коротких звонков ниже).
const analysisParsed = !!analysis;

if (!analysis) {
  analysis = {
    summary: '',
    overall_score: null,
    problem_level: 'HIGH',
    is_problem_call: true,
    channel_roles: {
      left: 'unknown',
      right: 'unknown',
      confidence: 'low',
      reason: 'AI вернул невалидный JSON'
    },
    main_strength: '',
    main_error: 'AI вернул невалидный JSON',
    recommended_feedback: 'Проверить звонок вручную.',
    rule_results: [],
    raw_ai_response: String(raw || '')
  };
}

analysis = {
  summary: String(analysis.summary || ''),
  overall_score: normalizeScore(analysis.overall_score),
  problem_level: normalizeProblemLevel(analysis.problem_level),
  is_problem_call: normalizeBoolean(analysis.is_problem_call),
  channel_roles: analysis.channel_roles || {
    left: 'unknown',
    right: 'unknown',
    confidence: 'low',
    reason: ''
  },
  main_strength: String(analysis.main_strength || ''),
  main_error: String(analysis.main_error || ''),
  recommended_feedback: String(analysis.recommended_feedback || ''),
  is_target_call: normalizeBoolean(analysis.is_target_call),
  non_target_reason: normalizeEnum(
    analysis.non_target_reason,
    ['spam', 'no_service', 'wrong_city', 'no_slots', 'off_hours', 'price', 'other'],
    ''
  ),
  non_target_detail: String(analysis.non_target_detail || ''),
  no_booking_reason: normalizeEnum(
    analysis.no_booking_reason,
    ['thinking', 'price', 'info_only', 'callback', 'declined', 'other'],
    ''
  ),
  no_booking_detail: String(analysis.no_booking_detail || ''),
  is_primary_patient: normalizeEnum(
    analysis.is_primary_patient,
    ['primary', 'repeat', 'unknown'],
    'unknown'
  ),
  requested_specialist_raw: String(analysis.requested_specialist_raw ?? analysis.requested_specialist ?? ''),
  is_appointment_booked: normalizeBoolean(analysis.is_appointment_booked),
  appointment_specialist_raw: String(analysis.appointment_specialist_raw ?? analysis.appointment_specialist ?? ''),
  appointment_datetime: String(analysis.appointment_datetime || ''),
  city: String(analysis.city || ''),
  referral_source: String(analysis.referral_source || ''),
  rule_results: asArray(analysis.rule_results)
    .map(r => ({
      rule_id: String(r.rule_id || ''),
      score: normalizeScore(r.score),
      is_na: normalizeBoolean(r.is_na),
      reason: String(r.reason || ''),
      evidence: String(r.evidence || ''),
      recommendation: String(r.recommendation || '')
    }))
    .filter(r => r.rule_id)
};

// --- Короткий звонок ---------------------------------------------------
// Build Analysis Request отдал сюда analysis_mode = 'short': обрыв, тишина
// или разговор на пару фраз. Модель по правилам его не оценивала — и не
// должна была, поэтому rule_results собираются кодом из evaluation_rules,
// все как N/A, а overall_score остаётся пустым.
//
// Заполняется именно весь список правил, а не пустой массив: вердикт-
// workflow и веб-интерфейс читают rule_results_json и ждут в нём строку
// на каждое правило.
const SHORT_CALL_NA_REASON = 'звонок слишком короткий для оценки';

if (meta.analysis_mode === 'short') {
  analysis.rule_results = (Array.isArray(meta.prompts?.evaluation_rules)
    ? meta.prompts.evaluation_rules
    : []
  )
    .map(rule => ({
      rule_id: String(rule?.rule_id || ''),
      score: null,
      is_na: true,
      reason: SHORT_CALL_NA_REASON,
      evidence: '',
      recommendation: ''
    }))
    .filter(r => r.rule_id);

  analysis.overall_score = null;

  // Проблемный уровень снимаем только если ответ модели вообще разобрался:
  // невалидный JSON остаётся HIGH и уходит на ручную проверку.
  if (analysisParsed) {
    analysis.problem_level = 'NONE';
    analysis.is_problem_call = false;
  }
}

// --- Матчинг специалистов по справочнику «Сотрудники» ------------------
// ВНИМАНИЕ: это JS-копия алгоритма из Apps Script (файл `code`,
// normalizeFio_ / matchEmployeeByName_ и их помощники). Реализации обязаны
// быть идентичны: менять их нужно синхронно в обоих местах, иначе оператор
// и специалисты начнут матчиться по разным правилам.
//
// Никакого fuzzy-матчинга: неуверенное совпадение — это NOT_FOUND,
// а не подстановка похожего сотрудника.

function normalizeFio(text) {
  return String(text === null || text === undefined ? '' : text)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^0-9a-zа-я]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Частые падежные окончания фамилий. Длинные — раньше коротких.
const FIO_CASE_ENDINGS = ['ому', 'ему', 'ым', 'им', 'ой', 'ей', 'а', 'у', 'ю'];

function stripFioCaseEnding(token) {
  const s = String(token || '');

  for (const ending of FIO_CASE_ENDINGS) {
    if (s.length - ending.length >= 3 && s.slice(-ending.length) === ending) {
      return s.slice(0, s.length - ending.length);
    }
  }

  return s;
}

function baseFioForm(normalized) {
  const tokens = String(normalized || '').split(' ').filter(Boolean);

  if (!tokens.length) return '';

  tokens[0] = stripFioCaseEnding(tokens[0]);

  return tokens.join(' ');
}

// Ключ короткой формы: фамилия + слитные инициалы.
// «солопова о с» → { last: 'солопова', initials: 'ос' }
// «кузнецов максим николаевич» → null (это не короткая форма)
function fioShortKey(normalized) {
  const tokens = String(normalized || '').split(' ').filter(Boolean);

  if (tokens.length < 2) return null;

  const rest = tokens.slice(1);

  if (rest.some(token => token.length > 2)) return null;

  const initials = rest.join('');

  if (!initials || initials.length > 2) return null;

  return { last: tokens[0], initials };
}

// Более короткий набор инициалов должен быть началом более длинного:
// в справочнике «Солопова О С», а прозвучать может «Солопова О».
function matchesFioShortForm(inputKey, employeeShortNormalized, useBase) {
  if (!inputKey) return false;

  const employeeKey = fioShortKey(employeeShortNormalized);

  if (!employeeKey) return false;

  const employeeLast = useBase ? stripFioCaseEnding(employeeKey.last) : employeeKey.last;

  if (inputKey.last !== employeeLast) return false;

  return inputKey.initials.indexOf(employeeKey.initials) === 0 ||
    employeeKey.initials.indexOf(inputKey.initials) === 0;
}

function describeEmployeeCandidates(candidates) {
  return 'Найдено несколько сотрудников: ' + candidates
    .slice(0, 10)
    .map(e => `${e.full_name} (${e.bitrix_user_id})`)
    .join(', ');
}

// status: EXACT | SHORT_EXACT | NAME_PATRONYMIC_UNIQUE | LASTNAME_UNIQUE |
//         NOT_FOUND | AMBIGUOUS | EMPTY
function matchEmployeeByName(name, employees, options) {
  const activeOnly = !(options && options.activeOnly === false);

  const result = { status: 'EMPTY', bitrix_user_id: '', full_name: '', comment: '' };

  const raw = String(name === null || name === undefined ? '' : name).trim();
  const normalized = normalizeFio(raw);

  if (!normalized) {
    result.comment = 'Имя не указано';
    return result;
  }

  const list = (Array.isArray(employees) ? employees : [])
    .map(e => ({
      bitrix_user_id: String(e.bitrix_user_id ?? ''),
      active: e.active === true || String(e.active).toLowerCase() === 'true',
      full_name: String(e.full_name ?? ''),
      full_name_normalized: String(e.full_name_normalized ?? '') || normalizeFio(e.full_name),
      short_name_normalized: String(e.short_name_normalized ?? ''),
      name_patronymic_normalized: String(e.name_patronymic_normalized ?? ''),
      last_name_normalized: String(e.last_name_normalized ?? '')
    }))
    .filter(e => (activeOnly ? e.active : true));

  if (!list.length) {
    result.status = 'NOT_FOUND';
    result.comment = 'Справочник сотрудников пуст';
    return result;
  }

  const shortKey = fioShortKey(normalized);

  // «Михаил Сергеевич» — минимум два токена. Одно имя («Михаил») никого
  // не идентифицирует и по имени-отчеству не матчится.
  const hasPatronymic = normalized.split(' ').filter(Boolean).length >= 2;

  const steps = [
    { status: 'EXACT', test: e => e.full_name_normalized === normalized },
    {
      status: 'SHORT_EXACT',
      test: e => e.short_name_normalized === normalized ||
        matchesFioShortForm(shortKey, e.short_name_normalized, false)
    },
    {
      status: 'NAME_PATRONYMIC_UNIQUE',
      comment: 'совпадение по имени и отчеству',
      test: e => hasPatronymic &&
        !!e.name_patronymic_normalized &&
        e.name_patronymic_normalized === normalized
    },
    { status: 'LASTNAME_UNIQUE', test: e => e.last_name_normalized === normalized }
  ];

  for (const step of steps) {
    const found = list.filter(step.test);

    if (found.length === 1) {
      result.status = step.status;
      result.bitrix_user_id = found[0].bitrix_user_id;
      result.full_name = found[0].full_name;
      result.comment = step.comment || '';
      return result;
    }

    if (found.length > 1) {
      result.status = 'AMBIGUOUS';
      result.comment = describeEmployeeCandidates(found);
      return result;
    }
  }

  // Падежные формы: «Коныховой», «Кузнецову». Статус не поднимается выше
  // LASTNAME_UNIQUE и допускается только при единственном кандидате.
  // К имени-отчеству падежный шаг не применяется.
  const base = baseFioForm(normalized);
  const baseKey = fioShortKey(base);

  const byCase = list.filter(e =>
    baseFioForm(e.full_name_normalized) === base ||
    baseFioForm(e.short_name_normalized) === base ||
    matchesFioShortForm(baseKey, e.short_name_normalized, true) ||
    stripFioCaseEnding(e.last_name_normalized) === base
  );

  if (byCase.length === 1) {
    result.status = 'LASTNAME_UNIQUE';
    result.bitrix_user_id = byCase[0].bitrix_user_id;
    result.full_name = byCase[0].full_name;
    result.comment = `падежная форма: ${raw} → ${base}`;
    return result;
  }

  if (byCase.length > 1) {
    result.status = 'AMBIGUOUS';
    result.comment = describeEmployeeCandidates(byCase);
    return result;
  }

  result.status = 'NOT_FOUND';
  result.comment = 'Не найдено надежное совпадение в справочнике сотрудников';

  return result;
}

// Автоподстановка ФИО разрешена только при этих статусах.
const CONFIDENT_MATCH_STATUSES = [
  'EXACT',
  'SHORT_EXACT',
  'NAME_PATRONYMIC_UNIQUE',
  'LASTNAME_UNIQUE'
];

// Справочник живёт в staticData workflow: его кладёт туда ветка приёма
// (вебхук /webhook/employees-directory, раз в сутки из Apps Script), и при
// звонке он только читается — в payload каждого звонка справочник больше
// не едет. Нормализованные формы посчитаны на приёме, здесь их не считаем.
//
// meta.employees — fallback на переходный период, пока Apps Script ещё
// кладёт справочник в payload. Убрать через неделю после деплоя вместе
// с полем employees в buildEmployeesPayload_ / sendTranscriptionRow_.
const staticData = $getWorkflowStaticData('global');

const employees = (Array.isArray(staticData.employees) && staticData.employees.length
  ? staticData.employees
  : meta.employees) || [];

// В requested_specialist / appointment_specialist попадает ТОЛЬКО full_name
// с листа «Сотрудники». Свободный текст AI живёт в *_raw и никуда больше.
const requestedMatch = matchEmployeeByName(analysis.requested_specialist_raw, employees);
const requestedConfirmed = CONFIDENT_MATCH_STATUSES.includes(requestedMatch.status);

const appointmentMatch = matchEmployeeByName(analysis.appointment_specialist_raw, employees);
const appointmentConfirmed = CONFIDENT_MATCH_STATUSES.includes(appointmentMatch.status);

// --- Подготовка записи в Google Sheets --------------------------------
// Имя листа в A1-нотации всегда берём в одинарные кавычки: в нём есть
// пробелы и кириллица («Записи звонков»).
function quoteSheetName(name) {
  return `'${String(name || '').replace(/'/g, "''")}'`;
}

// Лимит одной ячейки Google Sheets — 50 000 символов.
const MAX_CELL_LENGTH = 45000;

function cellText(value) {
  const s = String(value === null || value === undefined ? '' : value);
  return s.length > MAX_CELL_LENGTH
    ? `${s.slice(0, MAX_CELL_LENGTH)}…[обрезано]`
    : s;
}

const receivedAt = $now.toFormat('yyyy-MM-dd HH:mm:ss');

// Длительность: секунды — ЧИСЛОМ, «м:сс» — СТРОКОЙ.
// Запись идёт с valueInputOption=RAW (см. batchBody ниже), поэтому Sheets
// значения не разбирает и «2:20» не превращается во время. Формат самих
// колонок (число / текст) держит Apps Script — ensureDurationColumnFormats_
// в файле `code`: он и чинит значения, испорченные форматом даты.
function durationSecondsValue(value) {
  if (value === null || value === undefined || value === '') return '';

  const seconds = Number(value);

  return Number.isFinite(seconds) ? seconds : '';
}

const values = {
  transcription_received_at: receivedAt,
  transcription_error: '',
  call_duration_seconds: durationSecondsValue(meta.call_duration_seconds),
  call_duration: String(meta.call_duration || ''),
  transcript_text: cellText(meta.transcript_text),
  transcript_left: cellText(meta.transcript_channels?.left),
  transcript_right: cellText(meta.transcript_channels?.right),
  summary: cellText(analysis.summary),
  overall_score: analysis.overall_score === null ? '' : analysis.overall_score,
  problem_level: analysis.problem_level,
  is_problem_call: analysis.is_problem_call ? 'TRUE' : 'FALSE',
  main_strength: cellText(analysis.main_strength),
  main_error: cellText(analysis.main_error),
  recommended_feedback: cellText(analysis.recommended_feedback),
  is_target_call: analysis.is_target_call ? 'TRUE' : 'FALSE',
  non_target_reason: cellText(analysis.non_target_reason),
  non_target_detail: cellText(analysis.non_target_detail),
  no_booking_reason: cellText(analysis.no_booking_reason),
  no_booking_detail: cellText(analysis.no_booking_detail),
  is_primary_patient: cellText(analysis.is_primary_patient),
  requested_specialist_raw: cellText(analysis.requested_specialist_raw),
  requested_specialist: requestedConfirmed ? cellText(requestedMatch.full_name) : '',
  requested_specialist_bitrix_user_id: requestedConfirmed ? requestedMatch.bitrix_user_id : '',
  requested_specialist_match_status: requestedMatch.status,
  requested_specialist_match_comment: cellText(requestedMatch.comment),
  is_appointment_booked: analysis.is_appointment_booked ? 'TRUE' : 'FALSE',
  appointment_specialist_raw: cellText(analysis.appointment_specialist_raw),
  appointment_specialist: appointmentConfirmed ? cellText(appointmentMatch.full_name) : '',
  appointment_specialist_bitrix_user_id: appointmentConfirmed ? appointmentMatch.bitrix_user_id : '',
  appointment_specialist_match_status: appointmentMatch.status,
  appointment_specialist_match_comment: cellText(appointmentMatch.comment),
  appointment_datetime: cellText(analysis.appointment_datetime),
  city: cellText(analysis.city),
  referral_source: cellText(analysis.referral_source),
  rule_results_json: cellText(JSON.stringify(analysis.rule_results)),
  prompt_version: meta.prompt_version || meta.prompts?.prompt_version || '',
  transcription_n8n_execution_id: String($execution.id)
};

// Список полей приезжает из ноды Normalize Incoming Payload (RESULT_FIELDS).
// Он обязан совпадать 1:1 с константой RESULT_HEADERS в Apps Script (файл
// `code`): менять его нужно синхронно в обоих местах.
const fields = Array.isArray(meta.result_fields) && meta.result_fields.length
  ? meta.result_fields
  : Object.keys(values);

const withoutValue = fields.filter(f => values[f] === undefined);

if (withoutValue.length) {
  throw new Error(`No value prepared for result fields: ${withoutValue.join(', ')}`);
}

const withoutColumn = fields.filter(f => !meta.result_columns?.[f]);

if (withoutColumn.length) {
  throw new Error(`No column letter for result fields: ${withoutColumn.join(', ')}`);
}

const sheetPrefix = quoteSheetName(meta.sheet_name);

const sheetUpdates = fields.map(field => ({
  field,
  range: `${sheetPrefix}!${meta.result_columns[field]}${meta.row_number}`,
  value: values[field]
}));

return [
  {
    json: {
      call_key: meta.call_key,

      spreadsheet_id: meta.spreadsheet_id,
      sheet_name: meta.sheet_name,
      row_number: meta.row_number,

      sheetUpdates,

      // Одним запросом: values:batchUpdate вместо записи по одной ячейке.
      batchBody: {
        valueInputOption: 'RAW',
        data: sheetUpdates.map(u => ({ range: u.range, values: [[u.value]] }))
      },

      analysis,
      temp: meta.temp
    }
  }
];

// Общая ветка ошибок: сюда приходит error-выход любой ноды обработки.
// Пишем только transcription_error и transcription_received_at —
// остальные колонки строки не трогаем. Колонки специалистов
// (requested_specialist_*, appointment_specialist_*) и длительности
// при ошибке транскрибации остаются пустыми: матчинг живёт в ветке
// успеха (нода Prepare Sheet Update), здесь менять нечего.
const meta = $items('Normalize Incoming Payload')[0].json;
const item = $input.first();
const json = item.json || {};

const rawError = json.error !== undefined ? json.error : json;

function errorText(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value;

  const parts = [];

  if (value.message) parts.push(String(value.message));
  if (value.description && value.description !== value.message) {
    parts.push(String(value.description));
  }

  if (parts.length) return parts.join(' — ');

  try {
    return JSON.stringify(value).slice(0, 1500);
  } catch (e) {
    return String(value);
  }
}

const failedNode =
  json.error?.node?.name ||
  json.node?.name ||
  json.lastNodeExecuted ||
  '';

const message = [
  `n8n execution ${$execution.id}`,
  failedNode ? `нода «${failedNode}»` : '',
  errorText(rawError)
].filter(Boolean).join(': ');

function quoteSheetName(name) {
  return `'${String(name || '').replace(/'/g, "''")}'`;
}

const MAX_CELL_LENGTH = 45000;

const values = {
  transcription_error: message.length > MAX_CELL_LENGTH
    ? `${message.slice(0, MAX_CELL_LENGTH)}…[обрезано]`
    : message,
  transcription_received_at: $now.toFormat('yyyy-MM-dd HH:mm:ss')
};

const sheetPrefix = quoteSheetName(meta.sheet_name);

const sheetUpdates = Object.keys(values)
  .filter(field => meta.result_columns?.[field])
  .map(field => ({
    field,
    range: `${sheetPrefix}!${meta.result_columns[field]}${meta.row_number}`,
    value: values[field]
  }));

if (!sheetUpdates.length) {
  throw new Error('No result_columns for transcription_error / transcription_received_at');
}

return [
  {
    json: {
      call_key: meta.call_key,

      spreadsheet_id: meta.spreadsheet_id,
      sheet_name: meta.sheet_name,
      row_number: meta.row_number,

      failed_node: failedNode,
      error_message: message,

      sheetUpdates,

      batchBody: {
        valueInputOption: 'RAW',
        data: sheetUpdates.map(u => ({ range: u.range, values: [[u.value]] }))
      },

      temp: meta.temp
    }
  }
];

// Приём справочника сотрудников и запись его в staticData workflow.
//
// Зачем: раньше снимок листа «Сотрудники» ехал в payload КАЖДОГО звонка
// (десятки-сотни КБ на звонок, и всё это UrlFetch-трафик Apps Script).
// Теперь справочник кладётся сюда раз в сутки, а нода Prepare Sheet Update
// читает его из staticData.
//
// ОГРАНИЧЕНИЕ n8n: staticData сохраняется только при ПРОДАКШЕН-выполнениях
// активного workflow. Через «Execute workflow» в редакторе запись не
// переживёт выполнение — тестировать только реальным POST на активный
// workflow. При экспорте/импорте workflow staticData не переносится:
// после переимпорта справочник нужно запушить заново (force: true).
//
// Секрет проверяет сам вебхук (Header Auth, тот же credential
// X-TEMED-CALLS-SECRET, что у Mango-вебхука) — до этой ноды доходят
// только запросы с верным заголовком. Хардкодить секрет здесь нельзя:
// код ноды уезжает в git вместе с workflow.

// Не чаще раза в сутки. Порог чуть меньше 24 часов, чтобы суточный триггер
// Apps Script со «съехавшим» на минуты временем запуска не отбивался.
const MIN_REFRESH_INTERVAL_MS = 23 * 60 * 60 * 1000;

// Справочник для матчинга специалистов — только те, к кому вообще можно
// записаться. Подстроки ищутся в work_position без учёта регистра, в любой
// позиции: «Врач-невролог», «Инструктор ЛФК», «физиотерапевт».
const DIRECTORY_POSITION_PATTERNS = ['врач', 'лфк', 'терапевт', 'реабилитолог'];

const input = $input.first().json;
const body = input.body || input;

const staticData = $getWorkflowStaticData('global');

const force = body.force === true || String(body.force).toLowerCase() === 'true';

if (
  !force &&
  staticData.employees_updated_at &&
  Date.now() - staticData.employees_updated_at < MIN_REFRESH_INTERVAL_MS
) {
  return [
    {
      json: {
        status: 'SKIPPED_FRESH',
        updated_at: staticData.employees_updated_at,
        updated_at_text: staticData.employees_updated_at_text || '',
        count: Array.isArray(staticData.employees) ? staticData.employees.length : 0
      }
    }
  ];
}

// ВНИМАНИЕ: копия normalizeFio_ из Apps Script (файл `code`) и normalizeFio
// из ноды Prepare Sheet Update. Реализации обязаны быть идентичны — иначе
// справочник нормализуется по одним правилам, а имена из звонка по другим.
function normalizeFio(text) {
  return String(text === null || text === undefined ? '' : text)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^0-9a-zа-я]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isActive(value) {
  if (value === true) return true;
  if (value === false) return false;

  const s = String(value === null || value === undefined ? '' : value).trim().toLowerCase();

  return ['true', '1', 'yes', 'да', 'истина'].includes(s);
}

function isDirectoryPosition(workPosition) {
  const s = String(workPosition === null || workPosition === undefined ? '' : workPosition)
    .toLowerCase()
    .replace(/ё/g, 'е');

  return DIRECTORY_POSITION_PATTERNS.some(pattern => s.indexOf(pattern) !== -1);
}

const incoming = Array.isArray(body.employees) ? body.employees : [];

if (!incoming.length) {
  throw new Error('Missing employees array');
}

// Фильтры дублируют фильтры Apps Script намеренно: приёмник не доверяет
// тому, что прислали, и сам решает, кто попадает в справочник.
const employees = [];

let skippedInactive = 0;
let skippedPosition = 0;
let skippedNoName = 0;

for (const raw of incoming) {
  if (!raw || typeof raw !== 'object') continue;

  const fullName = String(raw.full_name ?? '').trim();

  if (!fullName) {
    skippedNoName++;
    continue;
  }

  if (!isActive(raw.active)) {
    skippedInactive++;
    continue;
  }

  if (!isDirectoryPosition(raw.work_position)) {
    skippedPosition++;
    continue;
  }

  const name = String(raw.name ?? '').trim();
  const secondName = String(raw.second_name ?? '').trim();

  // Нормализованные формы считаются ОДИН раз здесь и ложатся в staticData
  // готовыми: при каждом звонке идёт только чтение.
  employees.push({
    bitrix_user_id: String(raw.bitrix_user_id ?? ''),
    full_name: fullName,

    // Матчинг по умолчанию отбирает только активных (activeOnly), а
    // справочник уже отфильтрован — поле оставлено, чтобы matchEmployeeByName
    // работал без спецрежима.
    active: true,

    full_name_normalized: normalizeFio(fullName),
    short_name_normalized: normalizeFio(raw.short_name),
    last_name_normalized: normalizeFio(raw.last_name),
    name_patronymic_normalized: name
      ? normalizeFio([name, secondName].filter(Boolean).join(' '))
      : ''
  });
}

const updatedAt = Date.now();

staticData.employees = employees;
staticData.employees_updated_at = updatedAt;
staticData.employees_updated_at_text = new Date(updatedAt).toISOString();

return [
  {
    json: {
      status: 'OK',
      count: employees.length,
      received: incoming.length,
      skipped_inactive: skippedInactive,
      skipped_position: skippedPosition,
      skipped_no_name: skippedNoName,
      updated_at: updatedAt,
      updated_at_text: staticData.employees_updated_at_text
    }
  }
];
